CREATE OR REPLACE FUNCTION public.sw_notify() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE topic text; BEGIN IF TG_TABLE_NAME='participants' AND TG_OP='UPDATE' THEN IF to_jsonb(NEW)->>'admission_status' IS NOT DISTINCT FROM to_jsonb(OLD)->>'admission_status' AND to_jsonb(NEW)->>'display_name' IS NOT DISTINCT FROM to_jsonb(OLD)->>'display_name' THEN RETURN NEW; END IF; END IF; SELECT e.topic INTO topic FROM public.room_event_credentials e WHERE e.room_id=NEW.room_id; IF topic IS NOT NULL THEN PERFORM realtime.send('{}'::jsonb,'changed',topic,false); END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.sw_notify() FROM PUBLIC, anon, authenticated;